import{_ as s,o as i,c as e,a2 as n}from"./chunks/framework.BZO4qERu.js";const k=JSON.parse('{"title":"Linux常用命令","description":"","frontmatter":{},"headers":[],"relativePath":"linux/common-command.md","filePath":"linux/common-command.md","lastUpdated":1781086744000}'),t={name:"linux/common-command.md"};function l(p,a,o,h,d,c){return i(),e("div",null,[...a[0]||(a[0]=[n(`<h1 id="linux常用命令" tabindex="-1">Linux常用命令 <a class="header-anchor" href="#linux常用命令" aria-label="Permalink to &quot;Linux常用命令&quot;">​</a></h1><h2 id="查看系统相关命令" tabindex="-1">查看系统相关命令 <a class="header-anchor" href="#查看系统相关命令" aria-label="Permalink to &quot;查看系统相关命令&quot;">​</a></h2><h3 id="查看系统内核" tabindex="-1">查看系统内核 <a class="header-anchor" href="#查看系统内核" aria-label="Permalink to &quot;查看系统内核&quot;">​</a></h3><p>三个命令可以用来查看系统内核以及其他信息。</p><h4 id="_1-uname" tabindex="-1">1. uname <a class="header-anchor" href="#_1-uname" aria-label="Permalink to &quot;1. uname&quot;">​</a></h4><p>uname 是用来查看系统信息的命令。用法： <code>uname [OPTION]...</code>. 当没有option时，视为<code>uname -s</code>.</p><ul><li><code>-a</code> 打印所有信息</li><li><code>-s</code> 打印内核名称</li><li><code>-r</code> 打印内核发行版本</li><li>...其他见 <code>uname --help</code></li></ul><p>所以最直观的，可以用 <code>uname -r</code>来查看内核版本。</p><h4 id="_2-cat-proc-version" tabindex="-1">2. cat /proc/version <a class="header-anchor" href="#_2-cat-proc-version" aria-label="Permalink to &quot;2. cat /proc/version&quot;">​</a></h4><p><code>cat /proc/version</code> 可以打印系统版本信息。</p><h4 id="_3-hostnamectl" tabindex="-1">3. hostnamectl <a class="header-anchor" href="#_3-hostnamectl" aria-label="Permalink to &quot;3. hostnamectl&quot;">​</a></h4><p><code>hostnamectl</code>是用来控制系统主机名称的工具，也可以用来打印系统相关信息。</p><h3 id="查看系统版本" tabindex="-1">查看系统版本 <a class="header-anchor" href="#查看系统版本" aria-label="Permalink to &quot;查看系统版本&quot;">​</a></h3><p>不同的Linux发行版系统所用的命令不太一样。比较通用的可以使用</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cat /etc/*release</span></span></code></pre></div><h2 id="监控性能相关命令" tabindex="-1">监控性能相关命令 <a class="header-anchor" href="#监控性能相关命令" aria-label="Permalink to &quot;监控性能相关命令&quot;">​</a></h2><h3 id="top" tabindex="-1">top <a class="header-anchor" href="#top" aria-label="Permalink to &quot;top&quot;">​</a></h3><p>top命令用来监控Linux系统的性能，它可以实时地展示所有正在运行的进程，并且展示了CPU使用率，内存占用率等有用信息。</p><h3 id="vmstat" tabindex="-1">vmstat <a class="header-anchor" href="#vmstat" aria-label="Permalink to &quot;vmstat&quot;">​</a></h3><p>显示（虚拟）内存使用情况。</p><h3 id="ifconfig" tabindex="-1">ifconfig <a class="header-anchor" href="#ifconfig" aria-label="Permalink to &quot;ifconfig&quot;">​</a></h3><p>显示和设置网卡（network interface）。</p><h3 id="tcpdump" tabindex="-1">tcpdump <a class="header-anchor" href="#tcpdump" aria-label="Permalink to &quot;tcpdump&quot;">​</a></h3><p>用来对特定网卡抓包，同时提供过滤等功能，也可以把包数据保存下来，以供后续分析。</p><h3 id="netstat" tabindex="-1">netstat <a class="header-anchor" href="#netstat" aria-label="Permalink to &quot;netstat&quot;">​</a></h3><p>用来监控网络连接的状态。</p><h3 id="lscpu-lsmem" tabindex="-1">lscpu lsmem <a class="header-anchor" href="#lscpu-lsmem" aria-label="Permalink to &quot;lscpu lsmem&quot;">​</a></h3><p>分别可以用来查看CPU信息，内存信息。</p><h2 id="查看文件-目录-大小" tabindex="-1">查看文件（目录）大小 <a class="header-anchor" href="#查看文件-目录-大小" aria-label="Permalink to &quot;查看文件（目录）大小&quot;">​</a></h2><h3 id="ls" tabindex="-1">ls <a class="header-anchor" href="#ls" aria-label="Permalink to &quot;ls&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -lh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> filename</span></span></code></pre></div><ul><li><code>-l</code>表示每个文件（目录）显示一行</li><li><code>-h</code>表示使用 human readable 的形式输出。</li><li>不可用于查看目录大小。</li></ul><h3 id="du" tabindex="-1">du <a class="header-anchor" href="#du" aria-label="Permalink to &quot;du&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">du</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">filenam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">directory</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><ul><li><code>-s</code>表示只显示概要（也就是说当参数是目录的时候，不显示子目录信息）</li><li><code>-h</code>表示使用 human readable 的形式输出。</li><li>可用于查看文件和目录的大小。</li></ul><h2 id="sed-命令" tabindex="-1">sed 命令 <a class="header-anchor" href="#sed-命令" aria-label="Permalink to &quot;sed 命令&quot;">​</a></h2><p>Sed是一个用于修改文件的特殊编辑器。如果你想要写一个程序来改变一个文件，sed是一个很合适的工具。</p><h3 id="s子命令" tabindex="-1">s子命令 <a class="header-anchor" href="#s子命令" aria-label="Permalink to &quot;s子命令&quot;">​</a></h3><p>Sed含有几个命令，其中最常用的是s命令，用于字符替换。 <code>sed &#39;s/old/new&#39; </code>。</p><p>例如把文件中的<code>day</code>换成<code>night</code>可以使用如下命令</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 输入为文件old，输出到文件new</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sed</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> s/day/night/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">old</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">new</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> </span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 输入为echo输出的值，输出到控制台</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;day&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sed</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;s/day/night/&#39;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Output: night</span></span></code></pre></div><blockquote><p>分隔符也可以使用<code>_ : | </code>等，特别是当你要替换的字符里包含<code>/</code>时，那就必须使用其他的分隔符了。</p></blockquote><blockquote><p>注意在使用分隔符的时候，必须包含<strong>三个</strong>，少一个都不行。</p></blockquote><h3 id="支持正则表达式" tabindex="-1">支持正则表达式 <a class="header-anchor" href="#支持正则表达式" aria-label="Permalink to &quot;支持正则表达式&quot;">​</a></h3><p>sed命令支持正则表达式，-r参数可以使其支持扩展的正则表达式(extended regular expressions) &amp;用来指代寻到的pattern。(Mac OS上是-E）.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;123 abc&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sed</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;s/[0-9]+/(&amp;)/&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">123</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">abc</span></span></code></pre></div><h3 id="全局替换" tabindex="-1">全局替换 <a class="header-anchor" href="#全局替换" aria-label="Permalink to &quot;全局替换&quot;">​</a></h3><p><code>/g</code>用于全局替换。Sed在默认情况下只会对<strong>每一行</strong>的第一次配对成功的字符串进行替换。在替换的最后加上/g可以使所有匹配的字符串被替换.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;abc abc&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sed</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;s/abc/123/&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">123</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> abc</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;abc abc&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sed</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;s/abc/123/g&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">123</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 123</span></span></code></pre></div><h2 id="查看端口使用情况" tabindex="-1">查看端口使用情况 <a class="header-anchor" href="#查看端口使用情况" aria-label="Permalink to &quot;查看端口使用情况&quot;">​</a></h2><p>查看端口使用情况，一般使用两个命令：<code>netstat</code>或者<code>lsof</code>. 其中<code>netstat</code>是要一个用于监控网络的工具，而<code>lsof</code>是一个用于列出被某一个具体线程所打开的文件的工具。</p><h3 id="netstat-1" tabindex="-1">netstat <a class="header-anchor" href="#netstat-1" aria-label="Permalink to &quot;netstat&quot;">​</a></h3><ul><li>用于监控网络连接状况，路由表等</li><li>一般使用格式为 <code>netstat -nlp | grep &lt;port-number&gt;</code></li><li>其中<code>-n</code>代表以数字形式输出，<code>-l</code>代表显示正在监听的网络连接，<code>-p</code>代表显示与该连接对应的进程号和进程名</li><li><code>grep</code>用于筛选出我们需要的端口号。</li></ul><blockquote><p>以上是 Linux 系统中的<code>netstat</code>，与 Mac 中不一样。Mac中可以使用<code>netstat -na | grep &lt;port-number&gt;</code>来检查。</p></blockquote><p>查看各个端口的连接数情况</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>netstat -ant | awk &#39;/^tcp/{print $4}&#39; | awk -F: &#39;{print $(NF)}&#39; | sort | uniq -c | sort -nr | head</span></span></code></pre></div><h3 id="lsof" tabindex="-1">lsof <a class="header-anchor" href="#lsof" aria-label="Permalink to &quot;lsof&quot;">​</a></h3><ul><li>全称是 <code>list open files</code>，用于列出被某一个具体进程所打开的文件。这里的文件是广义上的文件，包括常规文件、目录、库、流或者网络文件（网络套接字，NFS文件，Unix域套接字等）。</li><li>直接输入<code>lsof</code>,会列出所有活跃进程打开的文件。</li><li>要查看占用某特定端口的进程，使用命令<code>lsof -i :&lt;port-number&gt;</code>.</li><li><code>-i [i]</code>的作用： <ul><li>列出网络地址符合一定规律的<code>network file</code>。该规律以<code>[i]</code>的格式展现。</li><li><code>[i]</code>的格式：<code>[46][protocol][@hostname|hostaddr][:service|port]</code></li><li>其具体含义为：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>46 specifies the IP version, IPv4 or IPv6</span></span>
<span class="line"><span>    that applies to the following address.</span></span>
<span class="line"><span>    &#39;6&#39; may be be specified only if the UNIX</span></span>
<span class="line"><span>    dialect supports IPv6.  If neither &#39;4&#39; nor</span></span>
<span class="line"><span>    &#39;6&#39; is specified, the following address</span></span>
<span class="line"><span>    applies to all IP versions.</span></span>
<span class="line"><span>protocol is a protocol name - TCP, UDP</span></span>
<span class="line"><span>hostname is an Internet host name.  Unless a</span></span>
<span class="line"><span>    specific IP version is specified, open</span></span>
<span class="line"><span>    network files associated with host names</span></span>
<span class="line"><span>    of all versions will be selected.</span></span>
<span class="line"><span>hostaddr is a numeric Internet IPv4 address in</span></span>
<span class="line"><span>    dot form; or an IPv6 numeric address in</span></span>
<span class="line"><span>    colon form, enclosed in brackets, if the</span></span>
<span class="line"><span>    UNIX dialect supports IPv6.  When an IP</span></span>
<span class="line"><span>    version is selected, only its numeric</span></span>
<span class="line"><span>    addresses may be specified.</span></span>
<span class="line"><span>service is an /etc/services name - e.g., smtp -</span></span>
<span class="line"><span>    or a list of them.</span></span>
<span class="line"><span>port is a port number, or a list of them.</span></span></code></pre></div><ul><li>举例如下： <ul><li><code>-i6</code> - IPv6 only</li><li><code>TCP:25</code> - TCP and port 25</li><li><code>@1.2.3.4</code> - Internet IPv4 host address 1.2.3.4</li><li><code>@[3ffe:1ebc::1]:1234</code> - Internet IPv6 host address 3ffe:1ebc::1, port 1234</li><li><code>UDP:who</code> - UDP who service port</li><li><code>TCP@lsof.itap:513</code> - TCP, port 513 and host name lsof.itap</li><li><code>tcp@foo:1-10,smtp,99</code> - TCP, ports 1 through 10, service name smtp, port 99, host name foo</li><li><code>tcp@bar:1-smtp - TCP</code>, ports 1 through smtp, host bar</li><li><code>:time</code> - either TCP, UDP or UDPLITE time service port</li></ul></li></ul></li></ul>`,58)])])}const u=s(t,[["render",l]]);export{k as __pageData,u as default};
